package com.pim.backend.taxonomy.model;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;

/**
 * A node of the product hierarchy (spec FR-001; data-model.md). It holds the system IDs of its direct attributes,
 * never the attributes themselves, so assignment changes never touch an attribute (FR-011).
 *
 * @param systemId generated by feature 003 (object type {@code CLASSIFICATION}); never changes (FR-002)
 * @param name unique among siblings ignoring letter case (FR-004)
 * @param description optional, up to 500 characters
 * @param parentId the parent's system ID; empty for a top-level node; changes only through a move (feature 011)
 * @param attributeIds direct attribute system IDs, upper-cased, in assignment order, each once (FR-009)
 * @param createdAt when the node was created
 * @param updatedAt when the name, description, assignments or parent last changed
 */
public record TaxonomyNode(
        String systemId,
        NodeName name,
        Optional<String> description,
        Optional<String> parentId,
        List<String> attributeIds,
        Instant createdAt,
        Optional<Instant> updatedAt) {

    /** Longest accepted description. */
    public static final int MAX_DESCRIPTION_LENGTH = 500;

    public TaxonomyNode {
        Objects.requireNonNull(systemId, "systemId");
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(description, "description");
        Objects.requireNonNull(parentId, "parentId");
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(updatedAt, "updatedAt");
        attributeIds = attributeIds.stream().map(TaxonomyNode::key).toList();
        Set<String> seen = new HashSet<>();
        for (String attributeId : attributeIds) {
            if (!seen.add(attributeId)) {
                throw new IllegalArgumentException("Attribute listed twice on node " + systemId + ": " + attributeId);
            }
        }
    }

    /**
     * A new node with no attributes.
     *
     * @throws InvalidNodeException {@code INVALID_NODE_DESCRIPTION} for a description longer than 500 characters
     */
    public static TaxonomyNode create(
            String systemId, NodeName name, String description, String parentId, Instant createdAt) {
        return new TaxonomyNode(
                systemId,
                name,
                normalizedDescription(description),
                Optional.ofNullable(parentId).map(TaxonomyNode::key),
                List.of(),
                createdAt,
                Optional.empty());
    }

    /**
     * The description trimmed; blank means absent.
     *
     * @throws InvalidNodeException {@code INVALID_NODE_DESCRIPTION} when longer than 500 characters
     */
    public static Optional<String> normalizedDescription(String description) {
        if (description == null || description.isBlank()) {
            return Optional.empty();
        }
        String trimmed = description.strip();
        if (trimmed.length() > MAX_DESCRIPTION_LENGTH) {
            throw new InvalidNodeException("description", TaxonomyErrorCode.INVALID_NODE_DESCRIPTION);
        }
        return Optional.of(trimmed);
    }

    /** The key used to store and compare system IDs: upper-cased. */
    public static String key(String systemId) {
        return systemId.toUpperCase(Locale.ROOT);
    }

    /** This node's storage key (its system ID upper-cased). */
    public String id() {
        return key(systemId);
    }

    /**
     * A copy with another name and description; ID, parent and assignments stay (FR-005).
     *
     * @throws InvalidNodeException {@code INVALID_NODE_DESCRIPTION} for a description longer than 500 characters
     */
    public TaxonomyNode renamed(NodeName newName, String newDescription, Instant at) {
        return new TaxonomyNode(
                systemId,
                newName,
                normalizedDescription(newDescription),
                parentId,
                attributeIds,
                createdAt,
                Optional.of(at));
    }

    /**
     * A copy under another parent; ID, name, description and assignments stay (feature 011 FR-001, FR-002). Its
     * descendants follow it because they point to it, not to its ancestors.
     *
     * @param newParentId the new parent's system ID, or {@code null} for the top level (FR-004)
     */
    public TaxonomyNode movedTo(String newParentId, Instant at) {
        return new TaxonomyNode(
                systemId,
                name,
                description,
                Optional.ofNullable(newParentId).map(TaxonomyNode::key),
                attributeIds,
                createdAt,
                Optional.of(at));
    }

    /** A copy with these attributes appended (those already direct are skipped). */
    public TaxonomyNode withAttributes(List<String> added, Instant at) {
        List<String> all = new ArrayList<>(attributeIds);
        for (String attributeId : added) {
            if (!hasDirect(attributeId)) {
                all.add(key(attributeId));
            }
        }
        return new TaxonomyNode(systemId, name, description, parentId, all, createdAt, Optional.of(at));
    }

    /** A copy without this direct attribute. */
    public TaxonomyNode withoutAttribute(String attributeId, Instant at) {
        String removed = key(attributeId);
        List<String> rest =
                attributeIds.stream().filter(id -> !id.equals(removed)).toList();
        return new TaxonomyNode(systemId, name, description, parentId, rest, createdAt, Optional.of(at));
    }

    /** Whether the attribute is assigned directly, comparing system IDs ignoring letter case. */
    public boolean hasDirect(String attributeId) {
        return attributeIds.contains(key(attributeId));
    }

    /** A reference to this node (system ID and name). */
    public NodeReference reference() {
        return new NodeReference(systemId, name.value());
    }
}
